"<script>
    const gridsData = {{ .GridsJSON }};
    const dayKeys = ["mon", "tue", "wed", "thu", "fri", "sat", "sun", "holiday"];
    const styleTracker = {};
    const durationTrackers = {};

    function toggleDayEnabled(prefix) {
        const checkbox = document.getElementById(`${prefix}-enabled`);
        const fieldsDiv = document.getElementById(`${prefix}-fields`);
        const inputs = fieldsDiv.querySelectorAll('input, select');

        if (checkbox.checked) {
            fieldsDiv.classList.remove('d-none');
            inputs.forEach(el => el.disabled = false);
            recalculateMetrics(prefix);
        } else {
            fieldsDiv.classList.add('d-none');
            inputs.forEach(el => el.disabled = true);
            recalculateMetrics(prefix);
        }
    }

    function copyMondayToDay(prefix) {
        document.getElementById(`${prefix}-start-time`).value = document.getElementById('mon-start-time').value;
        document.getElementById(`${prefix}-end-time`).value = document.getElementById('mon-end-time').value;
