func (r *MediaStyleRepository) Create(ctx context.Context, style models.MediaStyle) error {
	query := `
		INSERT INTO media_styles (
			id, tenant_id, media_type, name, description, base_directory, created_at
		) VALUES (
			$1, $2, $3, $4, $5, $6, NOW()
		)
	`
	_, err := database.Pool.Exec(ctx, query,
		style.ID, style.TenantID, style.MediaType, style.Name, style.Description, style.BaseDirectory,
	)
	return err
}

