"    function replicateStylesPattern(prefix, sourceBlockIdx, patternLen) {
        if (!customStyles[prefix]) {
            customStyles[prefix] = {};
        }

        let pattern = [];
        for (let k = 0; k < patternLen; k++) {
            let idx = sourceBlockIdx - 2 * (patternLen - 1 - k);
            if (idx >= 0) {
                let styles = customStyles[prefix][idx] || [];
                pattern.push([...styles]);
            }
        }

        if (pattern.length === 0) return;

        let P = pattern.length;
        for (let idx = sourceBlockIdx; idx < 300; idx += 2) {
            let patternOffset = Math.floor((idx - sourceBlockIdx) / 2) % P;
            customStyles[prefix][idx] = [...pattern[patternOffset]];
        }

        recalculateMetrics(prefix);
    }"

