"package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os/exec"
	"strconv"
)

type ffprobeFormat struct {
	Duration string            `json:"duration"`
	Size     string            `json:"size"`
	BitRate  string            `json:"bit_rate"`
	Tags     map[string]string `json:"tags"`
}

type ffprobeStream struct {
	CodecType  string `json:"codec_type"`
	SampleRate string `json:"sample_rate"`
}

type ffprobeData struct {
	Format  ffprobeFormat   `json:"format"`
	Streams []ffprobeStream `json:"streams"`
}

func main() {
	filePath := "midias/musicas/AGRADAVEIS_DANCE_TESTE/01 - get it right.mp3"
	fmt.Println("Running ffprobe on:", filePath)

	cmd := exec.Command("ffprobe", "-v", "quiet", "-print_format", "json", "-show_format", "-show_streams", filePath)
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		fmt.Printf("Error running ffprobe: %v\n", err)
		return
	}

	var data ffprobeData
	if err := json.Unmarshal(stdout.Bytes(), &data); err != nil {
		fmt.Printf("Error unmarshaling json: %v\n", err)
		return
	}

	var fileSizeBytes int64
	var bitRateKbps int
	var sampleRateHz int

	if s, err := strconv.ParseInt(data.Format.Size, 10, 64); err == nil {
		fileSizeBytes = s
	}

	if br, err := strconv.ParseFloat(data.Format.BitRate, 64); err == nil {
		bitRateKbps = int(br / 1000.0)
	}

	for _, stream := range data.Streams {
		if stream.CodecType == "audio" {
			if sr, err := strconv.Atoi(stream.SampleRate); err == nil {
				sampleRateHz = sr
				break
			}
		}
	}

	fmt.Printf("File Size: %d bytes\n", fileSizeBytes)
	fmt.Printf("Bitrate: %d kbps\n", bitRateKbps)
	fmt.Printf("Sample Rate: %d Hz\n", sampleRateHz)
}
"

