"package main

import (
	"context"
	"fmt"
	"imc-server/internal/database"
	"imc-server/internal/repository"
)

func main() {
	database.ConnectDatabase()
	if database.Pool == nil {
		fmt.Println("DB connection failed")
		return
	}

	trackRepo := repository.NewMusicTrackRepository()
	styleRepo := repository.NewMusicStyleRepository()

	styles, err := styleRepo.GetAll(context.Background())
	if err != nil {
		fmt.Println("Error getting styles:", err)
		return
	}

	for _, s := range styles {
		tracks, _ := trackRepo.GetByStyleID(context.Background(), s.ID)
		var totalSecs int
		for _, t := range tracks {
			totalSecs += t.DurationSeconds
		}
		fmt.Printf("Style: %s, TracksCount: %d, Calculated Total Seconds: %d\n", s.Name, len(tracks), totalSecs)
		if len(tracks) > 0 {
			fmt.Printf("Sample track: %s, Duration: %d seconds\n", tracks[0].FileName, tracks[0].DurationSeconds)
		}
	}
}
"

