"import json
import re
import os

transcript_path = r"C:\Users\molis\.gemini\antigravity\brain\586076c1-ef03-4ac6-9003-5a0c308b762c\.system_generated\logs\transcript.jsonl"

ssh_commands = []
if os.path.exists(transcript_path):
    with open(transcript_path, 'r', encoding='utf-8') as f:
        for line in f:
            if '"type":"RUN_COMMAND"' in line:
                try:
                    data = json.loads(line)
                    if 'tool_calls' in data and data['tool_calls']:
                        for tc in data['tool_calls']:
                            if tc.get('name') == 'run_command':
                                cmd = tc.get('args', {}).get('CommandLine', '')
                                if cmd and 'ssh dreams' in cmd:
                                    ssh_commands.append(cmd)
                except Exception as e:
                    pass

# Get unique commands, preserving order of appearance
seen = set()
unique_ssh = []
for c in ssh_commands:
    if c not in seen:
        seen.add(c)
        unique_ssh.append(c)

print(f"Found {len(unique_ssh)} unique SSH commands. Showing last 20:")
for c in unique_ssh[-20:]:
    print("---")
    print(c)
