"const fs = require('fs');
const readline = require('readline');

const transcriptPath = "C:\\Users\\molis\\.gemini\\antigravity\\brain\\586076c1-ef03-4ac6-9003-5a0c308b762c\\.system_generated\\logs\\transcript.jsonl";

async function processLineByLine() {
  const fileStream = fs.createReadStream(transcriptPath);

  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  const sshCommands = [];

  for await (const line of rl) {
    if (line.includes('"type":"RUN_COMMAND"')) {
      try {
        const data = JSON.parse(line);
        if (data.tool_calls) {
          for (const tc of data.tool_calls) {
            if (tc.name === 'run_command') {
              const cmd = tc.args.CommandLine;
              if (cmd && cmd.includes('ssh dreams')) {
                sshCommands.push(cmd);
              }
            }
          }
        }
      } catch (err) {
        // ignore JSON parse errors
      }
    }
  }

  const uniqueSsh = [];
  const seen = new Set();
  for (const c of sshCommands) {
    if (!seen.has(c)) {
      seen.add(c);
      uniqueSsh.push(c);
    }
  }

  console.log(`Found ${uniqueSsh.length} unique SSH commands. Showing last 30:`);
  for (const c of uniqueSsh.slice(-30)) {
    console.log("---");
    console.log(c);
  }
}

processLineByLine();
"

