	track, err := musicTrackRepo.GetByID(ctx, trackID)
	if err != nil || track == nil {
		http.Error(w, "Track not found", http.StatusNotFound)
		return
	}

	track.CueIn = req.CueIn
	track.CueOut = req.CueOut
	track.ManualCue = true

