"    function switchCategoryTab(category, btnElement) {
        activeCategory = category;

        // Update active class on buttons
        const listItems = document.querySelectorAll('.list-group-custom .list-group-item');
        listItems.forEach(item => item.classList.remove('active'));
        if (btnElement) {
            btnElement.classList.add('active');
        }

        // Update list title
        const listTitles = {
            ALL: "📋 Todos os Comerciais e Eventos",
            COMMERCIAL: "📣 Comerciais (Patrocínio / Anúncio)",
            OFFER: "🏷️ Ofertas",
            INSTITUTIONAL: "🏢 Institucionais",
            BLOCK_OPENING: "🔓 Aberturas de Bloco",
            BLOCK_CLOSING: "🔒 Fechamentos de Bloco",
            EVENT: "📅 Eventos Especiais",
            GENERAL_INFORMATION: "ℹ️ Informativos",
            RIGHT_TIME: "⏰ Hora Certa",
            TEMPERATURE: "🌡️ Temperatura"
        };
        document.getElementById('list-title').innerText = listTitles[category] || "📋 Comerciais e Eventos";

        // Filter rows
        const rows = document.querySelectorAll('.commercial-row');
        let visibleCount = 0;
        rows.forEach(row => {
            const rowType = row.getAttribute('data-type');
            if (category === 'ALL' || rowType === category) {
                row.classList.remove('d-none');
                visibleCount++;
            } else {
                row.classList.add('d-none');
            }
        });

        // Toggle "No items" row
        let noItemsRow = document.getElementById('no-items-row');
        if (visibleCount === 0) {
            if (noItemsRow) noItemsRow.classList.remove('d-none');
        } else {
            if (noItemsRow) noItemsRow.classList.add('d-none');
        }
    }"

