        /* Collapsible Sidebar Styles */
        @media (min-width: 768px) {
            #main-layout-container {
                display: flex;
                flex-wrap: nowrap;
                min-height: 100vh;
            }
            .sidebar {
                flex: 0 0 240px;
                width: 240px;
                max-width: 240px;
                transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            }
            main {
                flex: 1;
                width: 100%;
                transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            }

            /* Collapsed State */
            .sidebar-collapsed .sidebar {
                flex: 0 0 75px;
                width: 75px;
