"    // --- LOCAL FILES LISTING PREVIEW ---
    function initLocalAudioPreview(inputElement) {
        const files = inputElement.files;
        const section = document.getElementById('waveform-preview-section');
        const listContainer = document.getElementById('preview-files-list');

        if (!files || files.length === 0) {
            if (section) section.classList.add('d-none');
            if (listContainer) listContainer.innerHTML = '';
            return;
        }

        if (section) section.classList.remove('d-none');
        if (listContainer) listContainer.innerHTML = '';

        Array.from(files).forEach((file) => {
            const li = document.createElement('li');
            const sizeMB = (file.size / (1024 * 1024)).toFixed(2);
            li.innerHTML = `🎵 <strong>${file.name}</strong> <span class="text-white-50">(${sizeMB} MB)</span>`;
            listContainer.appendChild(li);
        });
    }"

