"    // --- WAVESURFER PREVIEW ENGINE ---
    let selectedFiles = [];
    let currentPreviewIndex = 0;

    function initLocalAudioPreview(inputElement) {
        const files = inputElement.files;
        const section = document.getElementById('waveform-preview-section');
        const listContainer = document.getElementById('preview-files-list');

        if (!files || files.length === 0) {
            selectedFiles = [];
            if (section) section.classList.add('d-none');
            if (listContainer) listContainer.innerHTML = '';
            if (wavesurfer) {
                try { wavesurfer.destroy(); } catch (e) {}
                wavesurfer = null;
            }
            return;
        }

        selectedFiles = Array.from(files);
        if (section) section.classList.remove('d-none');
        if (listContainer) listContainer.innerHTML = '';

        selectedFiles.forEach((file, index) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = `btn btn-sm ${index === 0 ? 'btn-primary' : 'btn-outline-primary'} text-truncate`;
            btn.style.maxWidth = '250px';
            btn.innerText = file.name;
            btn.id = `preview-file-btn-${index}`;
            btn.onclick = () => loadPreviewFile(index);
            listContainer.appendChild(btn);
        });

        loadPreviewFile(0);
    }

    function loadPreviewFile(index) {
        if (index < 0 || index >= selectedFiles.length) return;

        selectedFiles.forEach((_, idx) => {
            const btn = document.getElementById(`preview-file-btn-${idx}`);
