"    function updateInlineDistributionView() {
        const distributeToAll = document.getElementById('distribute_to_all').checked;
        const section = document.getElementById('inline-distribution-section');
        if (!section) return;

        if (distributeToAll) {
            section.classList.add('d-none');
            document.querySelectorAll('.inline-store-checkbox').forEach(cb => cb.checked = false);
            document.querySelectorAll('.inline-select-all-tenant-stores').forEach(cb => {
                cb.checked = false;
                cb.indeterminate = false;
            });
        } else {
            section.classList.remove('d-none');

            // Get all checked matrix/tenant IDs
            const checkedTenantCbs = document.querySelectorAll('.form-tenant-cb:checked');
            const selectedTenantIds = Array.from(checkedTenantCbs).map(cb => cb.value);

            // If the element doesn't exist (not admin), we just show all groups
            const hasTenantsDropdown = document.querySelectorAll('.form-tenant-cb').length > 0;
            const isGlobal = selectedTenantIds.includes('00000000-0000-0000-0000-000000000000');

            document.querySelectorAll('.inline-tenant-group').forEach(group => {
                const groupTenantId = group.getAttribute('data-tenant-id');
                if (!hasTenantsDropdown || isGlobal || selectedTenantIds.includes(groupTenantId)) {
                    group.classList.remove('d-none');
                } else {
                    group.classList.add('d-none');
                    group.querySelectorAll('.inline-store-checkbox').forEach(cb => cb.checked = false);
                    const selectAllCb = group.querySelector('.inline-select-all-tenant-stores');
                    if (selectAllCb) {
                        selectAllCb.checked = false;
                        selectAllCb.indeterminate = false;
                    }
                }
            });
        }
    }"

