"    function updateFormTypeRules() {
        const select = document.getElementById('commercial_type_select');
        const ruleText = document.getElementById('type-rule-text');
        const eventTimeContainer = document.getElementById('event_time_container');
        const executionTimeInput = document.getElementById('execution_time_input');
        const dailyTimeFieldsContainer = document.getElementById('daily_time_fields_container');

        if (select) {
            const val = select.value;
            if (ruleText) {
                ruleText.innerText = typeRules[val] || "Selecione um tipo de mídia.";
            }
            if (eventTimeContainer && executionTimeInput) {
                if (val === 'EVENT') {
                    eventTimeContainer.classList.remove('d-none');
                    executionTimeInput.required = true;
                    if (dailyTimeFieldsContainer) {
                        dailyTimeFieldsContainer.classList.add('d-none');
                        const startTimeInput = dailyTimeFieldsContainer.querySelector('input[name="start_time"]');
                        const endTimeInput = dailyTimeFieldsContainer.querySelector('input[name="end_time"]');
                        if (startTimeInput) startTimeInput.value = '00:00';
                        if (endTimeInput) endTimeInput.value = '23:59';
                    }
                } else {
                    eventTimeContainer.classList.add('d-none');
                    executionTimeInput.required = false;
                    executionTimeInput.value = '';
                    if (dailyTimeFieldsContainer) {
                        dailyTimeFieldsContainer.classList.remove('d-none');
                    }
                }
            }
        }
    }"

