"    function filterTenantsDropdownList(input, itemSelector) {
        const filter = input.value.toLowerCase().trim();
        document.querySelectorAll(itemSelector).forEach(item => {
            const nameAttr = item.getAttribute('data-search-name') || '';
            const isGlobalVal = item.querySelector('#filter-tenant-global') || item.querySelector('#form-tenant-global');
            if (isGlobalVal || nameAttr.toLowerCase().includes(filter)) {
                item.classList.remove('d-none');
            } else {
                item.classList.add('d-none');
            }
        });
    }

    let activeSortColIndex = 1;
    let activeSortDataType = 'string';
    let activeSortDir = 'asc';
    let commercialSortDirections = {};

    function sortCommercials(colIndex, dataType, forceDir) {
        const table = document.querySelector('table');
        if (!table) return;
        const tbody = table.querySelector('tbody');
        if (!tbody) return;
        const rows = Array.from(tbody.querySelectorAll('.commercial-row'));
        if (rows.length === 0) return;

        const key = 'comm-' + colIndex;
        let nextDir = 'asc';
        if (forceDir) {
            nextDir = forceDir;
        } else {
            const currentDir = commercialSortDirections[key] || 'desc';
            nextDir = currentDir === 'asc' ? 'desc' : 'asc';
        }
        commercialSortDirections[key] = nextDir;
        activeSortColIndex = colIndex;
        activeSortDataType = dataType;
        activeSortDir = nextDir;
        localStorage.setItem('imc_comm_sort', JSON.stringify({ colIndex, dataType, dir: nextDir }));

        const headers = table.querySelectorAll('thead th');
        headers.forEach((th, idx) => {
            if (idx === colIndex) {
                th.setAttribute('data-sort-dir', nextDir);
                th.style.color = 'var(--primary-color)';
                th.innerHTML = th.innerHTML.replace(/ [▲▼]/g, '') + (nextDir === 'asc' ? ' ▲' : ' ▼');

