+    function parseDurationToSeconds(str) {
+        if (!str || str === '--') return 0;
+        if (str.includes(':')) {
+            let parts = str.split(':');
+            let m = parseInt(parts[0]) || 0;
+            let s = parseFloat(parts[1]) || 0;
+            return m * 60 + s;
+        }
+        return parseFloat(str.replace(/[^\d.-]/g, '')) || 0;
