+    function parsePeriodToTimestamp(str) {
+        if (!str || str === '--') return 0;
+        let parts = str.split(' à ');
+        let dateStr = parts[0].trim();
+        let dateParts = dateStr.split('/');
+        if (dateParts.length === 3) {
+            let day = parseInt(dateParts[0]) || 0;
+            let month = parseInt(dateParts[1]) || 0;
+            let year = parseInt(dateParts[2]) || 0;
