"    function filterTable() {
        const query = document.getElementById('search-input').value.toLowerCase();
        const resourceFilter = document.getElementById('filter-resources').value;
        const rows = document.querySelectorAll('.store-row');

        rows.forEach(row => {
            const storeName = row.querySelector('.td-store-name').innerText.toLowerCase();
            const regional = row.querySelector('.td-regional').innerText.toLowerCase();
            const tenant = row.querySelector('.td-tenant').innerText.toLowerCase();
            const location = row.querySelector('.td-location').innerText.toLowerCase();

            // Check resources from data attributes
            const hasAudio = row.getAttribute('data-has-audio') === 'true';
            const hasVideo = row.getAttribute('data-has-video') === 'true';

            let matchesQuery = storeName.includes(query) || regional.includes(query) || tenant.includes(query) || location.includes(query);
            let matchesResource = false;

            if (resourceFilter === 'all') {
                matchesResource = true;
            } else if (resourceFilter === 'audio') {
                matchesResource = hasAudio;
            } else if (resourceFilter === 'video') {
                matchesResource = hasVideo;
            } else if (resourceFilter === 'both') {
                matchesResource = hasAudio && hasVideo;
            }

            if (matchesQuery && matchesResource) {
                row.style.display = "";
            } else {
                row.style.display = "none";
            }
        });
    }

    // Inicializa o filtro de regionais e grades no carregamento inicial da página
    window.onload = function() {
        filterTenantDependents();
    };"

