"    function cancelEdit() {
        document.getElementById('grid-id').value = "";
        document.getElementById('grid-form').action = "/dashboard/grids/audio/create";
        document.getElementById('form-title').innerText = "📅 Cadastrar Nova Grade de Áudio";
        document.getElementById('submit-btn').innerText = "💾 Gravar Grade";
        document.getElementById('grid-form').reset();

        customDurations = {};
        customStyles = {};
        document.getElementById('tenant-id').value = "00000000-0000-0000-0000-000000000000";

        dayKeys.forEach(prefix => {
            if (prefix !== 'mon') {
                document.getElementById(`${prefix}-enabled`).checked = false;
                toggleDayEnabled(prefix);
            }
        });

        document.getElementById('form-view').classList.remove('d-block');
        document.getElementById('form-view').classList.add('d-none');
        document.getElementById('list-view').classList.remove('d-none');
        document.getElementById('list-view').classList.add('d-block');
    }

    let currentPage = 1;
    let totalPages = 1;
    let itemsPerPage = 50;

    function initPagination() {
        const savedLimit = localStorage.getItem('imc_table_limit');
        if (savedLimit) {
            itemsPerPage = savedLimit === 'ALL' ? 'ALL' : parseInt(savedLimit) || 50;
        } else {
            itemsPerPage = 50;
        }
        const limitSelect = document.getElementById('pagination-limit-select');
        if (limitSelect) {
            limitSelect.value = itemsPerPage;
        }
